package com.mockarena.assessment.domain; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="attempt_item_results",schema="assessment")@IdClass(AttemptItemResponseId.class) public class AttemptItemResult{@Id private UUID attemptId;@Id private int globalPosition;@Column(nullable=false)private UUID questionId,questionVersionId;@Column(nullable=false)private String questionTypeCode;@Enumerated(EnumType.STRING)@Column(nullable=false)private ItemEvaluationStatus evaluationStatus;@Enumerated(EnumType.STRING)private EvaluationOutcome outcome;private BigDecimal awardedScore,maxScore;private Instant evaluatedAt;protected AttemptItemResult(){}public AttemptItemResult(AttemptItem i,ItemEvaluationStatus s,EvaluationOutcome o,BigDecimal score,BigDecimal max,Instant at){attemptId=i.attemptId();globalPosition=i.globalPosition();questionId=i.questionId();questionVersionId=i.questionVersionId();questionTypeCode=i.questionTypeCode();evaluationStatus=s;outcome=o;awardedScore=score;maxScore=max;evaluatedAt=at;}public void replace(ItemEvaluationStatus s,EvaluationOutcome o,BigDecimal score,BigDecimal max,Instant at){evaluationStatus=s;outcome=o;awardedScore=score;maxScore=max;evaluatedAt=at;}public UUID attemptId(){return attemptId;}public int globalPosition(){return globalPosition;}public UUID questionId(){return questionId;}public UUID questionVersionId(){return questionVersionId;}public String questionTypeCode(){return questionTypeCode;}public ItemEvaluationStatus evaluationStatus(){return evaluationStatus;}public EvaluationOutcome outcome(){return outcome;}public BigDecimal awardedScore(){return awardedScore;}public BigDecimal maxScore(){return maxScore;}public Instant evaluatedAt(){return evaluatedAt;}}
